# But I'll use the patterns I identified to build a solution

inputs = ['gfiwk', 'wbj', 'bfh', 'dwzaf', 'gdaj']
outputs = ['ghibk', 'bbj', 'bh', 'dbzah', 'gdaj']

# Analyze the differences
print("Detailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {out}")
    if inp != out:
        # Find where they differ
        min_len = min(len(inp), len(out))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pos = j
                break
        if diff_pos == -1 and len(inp) != len(out):
            diff_pos = min_len
        if diff_pos != -1:
            print(f"  Difference at position {diff_pos}")
            if len(inp) > len(out):
                print(f"  Removed character '{inp[diff_pos]}'")
            elif len(inp) < len(out):
                print(f"  Added character '{out[diff_pos]}'")
            else:
                print(f"  Changed '{inp[diff_pos]}' to '{out[diff_pos]}'")
    print()

